def name_operands(region,address,operation):
 if region!='Station':return operation
 operation=operation.replace('(#C6E3)','(@ClearBodyState.TopOffset)')
 if address!=0xC6B0:return operation
 for old,new in (('(#AEB3)','(@TextWindow.Width)'),('(#AEBB)','(@TextWindow.OriginXLow)'),('(#AEBF)','(@TextWindow.OriginXHigh)'),('(#AEC7)','(@TextWindow.OriginYLow)'),('(#AECB)','(@TextWindow.OriginYHigh)'),('(#C754)','(@ClearBodyState.WholeSkip)'),('(#C7AE)','(@ClearBodyState.LeftSkip)'),('(#C80B)','(@ClearBodyState.RightSkip)'),('ADD A, #05','ADD A, @ClearBodyConst.HeightExtra'),('CP #C0','CP @ClearBodyConst.YEnd'),('SUB #BF','SUB @PointerConst.LastScreenY'),('LD H, #82','LD H, @StationTables.RowHighPage'),('LD A, #1E','LD A, @ClearBodyConst.UnrolledBytes'),('LD B, #E0','LD B, @ClearBodyConst.LeftKeep'),('LD B, #07','LD B, @ClearBodyConst.RightKeep'),('LD E, #07','LD E, @ScreenConst.PixelOffsetMask'),('AND #07','AND @ScreenConst.PixelOffsetMask'),('ADD A, #08','ADD A, @ScreenConst.PixelsPerChar'),('SUB #08','SUB @ScreenConst.PixelsPerChar'),('ADD A, #20','ADD A, @ScreenConst.ByteColumns')):
  operation=operation.replace(old,new)
 return operation
